/bin/bash -c "python3 - <<'PY'
# Check the role-link information retained by Algorithm 1 on a minimal,
# schema-valid pair of MethodStep events. This is a check of the written
# representation, not an execution of the authors' implementation.
gold={('t1','BaseComponent','a'),('t2','TriedComponent','a')}
swapped={('t1','TriedComponent','a'),('t2','BaseComponent','a')}
def encode(events):
    return ({(t,a) for t,r,a in events},{(a,r) for t,r,a in events})
def decode(encoded):
    links,typed_args=encoded
    return {(t,r,a) for t,a in links for a2,r in typed_args if a==a2}
print('Two different event structures encode identically:',encode(gold)==encode(swapped))
print('Gold relations:',sorted(gold))
print('Algorithm 1 decoded relations:',sorted(decode(encode(gold))))
PY"
